+    // Private histograms to avoid cache contention on global hist
+    constexpr int SUB_HIST = 4;
+    uint32_t hist_priv[SUB_HIST][256] = {0};
+    
+    // Running sums for the two vector lanes
+    int64x2_t sum0 = vdupq_n_s64(0);
+    int64x2_t sum1 = vdupq_n_s64(0);
+    
+    size_t i = 0;
+    // Process pairs of elements
+    for (; i + 1 < n; i += 2) {
+        // Load two int64 values
+        int64x2_t a = vld1q_s64(in + i);
+        int64x2_t b = vld1q_s64(in + i + 1);
+        
+        // Prefix sum: accumulate into running sums
+        sum0 = vaddq_s64(sum0, a);
+        sum1 = vaddq_s64(sum1, b);
+        
+        // Extract low bytes (shift right by 56 bits)
+        uint8x8_t byte_a = vshrn_n_u64(vreinterpretq_u64_s64(a), 56);
+        uint8x8_t byte_b = vshrn_n_u64(vreinterpretq_u64_s64(b), 56);
