+        // Increment private histograms
+        hist_priv[byte_a[0] & 3][byte_a[0]]++;
+        hist_priv[byte_b[0] & 3][byte_b[0]]++;
+        hist_priv[byte_a[1] & 3][byte_a[1]]++;
+        hist_priv[byte_b[1] & 3][byte_b[1]]++;
